                "inputs": [
                    {"name": "a", "type": "uint32"},
                    {"name": "b", "type": "bool"},
                ],
            }
        )
        data = word(7) + (b"\x00" * 31 + b"\x01")
        self.assertEqual(
            decode_event_log(event, [bytes.fromhex(event_topic0(event)[2:])], data),
            (7, True),
        )

    def test_all_indexed_non_anonymous_requires_empty_data(self):
