        )
        self.assertEqual(result, (ADDR_A,))
        result2 = decode_event_log(
            event, [bytes.fromhex(event_topic0(event)[2:]), addr_word(ADDR_A)], ""
        )
        self.assertEqual(result2, (ADDR_A,))

